import click
from click.testing import CliRunner


def test_invalid_integer_rejected_before_callback():
    callback_calls = []

    @click.command()
    @click.option("--count", type=int)
    def command(count):
        callback_calls.append(count)

    result = CliRunner().invoke(command, ["--count", "not-an-integer"])

    assert result.exit_code == 2
    assert callback_calls == []

import click
from click.testing import CliRunner


def test_integer_range_inclusive_bounds_and_rejections():
    received = []

    @click.command()
    @click.option("--count", type=click.IntRange(1, 3))
    def command(count):
        received.append(count)

    runner = CliRunner()
    for value, expected in [("1", 1), ("3", 3)]:
        result = runner.invoke(command, ["--count", value])
        assert result.exit_code == 0
        assert received[-1] == expected

    accepted_calls = list(received)
    for value in ("0", "4"):
        result = runner.invoke(command, ["--count", value])
        assert result.exit_code == 2
        assert received == accepted_calls

import click
from click.testing import CliRunner


def test_integer_range_inclusive_bounds_and_rejections():
    received = []

    @click.command()
    @click.option("--count", type=click.IntRange(1, 3))
    def command(count):
        received.append(count)

    runner = CliRunner()
    for value, expected in [("1", 1), ("3", 3)]:
        result = runner.invoke(command, ["--count", value])
        assert result.exit_code == 0
        actual = received[-1]
        assert isinstance(actual, int) and not isinstance(actual, bool)
        assert actual == expected

    accepted_calls = list(received)
    for value in ("0", "4"):
        result = runner.invoke(command, ["--count", value])
        assert result.exit_code == 2
        assert received == accepted_calls

